package com.ecole.gestion_scolaire.transport.entity;
import jakarta.persistence.*; import java.time.*; import java.math.*;
@Entity @Table(name="student_transport_assignment") public class StudentTransportAssignment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="student_enrollment_id") public Long studentEnrollmentId; @Column(name="route_id") public Long routeId; @Column(name="stop_id") public Long stopId; @Column(name="service_type") public String serviceType; @Column(name="monthly_fee") public BigDecimal monthlyFee; @Column(name="start_date") public LocalDate startDate; @Column(name="end_date") public LocalDate endDate; public String status; @Column(name="created_at") public OffsetDateTime createdAt; @Column(name="updated_at") public OffsetDateTime updatedAt; @PrePersist void p(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;if(status==null)status="ACTIVE";} @PreUpdate void u(){updatedAt=OffsetDateTime.now();} }
